void tacho_fiq_service( void )
{
	UInt32 time_fiq   ;
    UInt32 time_diff  ;    
    
    if( gpio_pl_int_stat_r(GPIO_PL_INPUT_TACH) )
	{
		gpio_pl_int_clr(GPIO_PL_INPUT_TACH);

		time_fiq = fiq_get_tc( FIQ_TC_TIMER_1 ) ; 

    	time_diff = ( time_fiq > tacho_time ) ?  time_fiq-tacho_time : (0xFFFFFFFF - tacho_time)+time_fiq ; 

		if( time_diff >  tacho_noise )
		{
			tacho_time = time_fiq ; 

			tacho_value = tacho_filter_update( time_diff );

			tmr_dis( tacho_tmr ) ; 
		
			tmr_update( tacho_tmr  ,  TACHO_TIMEOUT , TRUE );
		
			tmr_ena( tacho_tmr ); 
		}			
	}

	if( tmr_int_sta( tacho_tmr ) )
	{
		tmr_dis(tacho_tmr) ; 
		
		tacho_time             = 0;

		tacho_value            = 0;

		tacho_filter_reset() ;
	}
}

